import random
import math
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_formula(n):
        if n == 1:
            return 'x'
        else:
            subformulas = [generate_boolean_formula(random.randint(1, n-1)) for _ in range(2)]
            return f'({subformulas[0]} & {subformulas[1]}) | (~{subformulas[0]} & ~{subformulas[1]})'

    def frege_proof_width(formula):
        if formula.startswith('(') and formula.endswith(')'):
            formula = formula[1:-1]
        if ' & ' in formula:
            return max(frege_proof_width(subformula) for subformula in formula.split(' & '))
        elif ' | ' in formula:
            return max(frege_proof_width(subformula) for subformula in formula.split(' | '))
        else:
            return 1

    n = random.randint(5, 40)
    formula = generate_boolean_formula(n)
    rank = frege_proof_width(formula)

    expected_rank = n**2 * math.log2(n)**2
    if rank < expected_rank:
        counterexample = f"rank={rank}, expected={expected_rank}"
        return {
            "metric_name": "minimal_rank",
            "metric_value": rank,
            "instances_tested": 1,
            "conjecture_holds": False,
            "counterexample": counterexample
        }
    else:
        return {
            "metric_name": "minimal_rank",
            "metric_value": rank,
            "instances_tested": 1,
            "conjecture_holds": True,
            "counterexample": ""
        }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i - 1 for i in range(5, 30)]

    results = []
    for seed in seeds:
